import math
def priority(task, state, due_w=1.0, spt_w=0.05, age_w=0.01, c=3.0, demote=0.25, m=1e6, floor=0.2):
    ref = max(state.mean_est, 1.0)
    est = max(task.estimated_runtime, floor * ref, 1e-6)
    wait = max(0.0, state.now - task.release)
    inv = 1.0 / est

    score = -due_w * task.due / ref + spt_w * ref * inv + age_w * wait * inv

    if task.tenant == 'premium':
        slack = task.due - state.now - est
        backlog = state.queue_work / max(state.capacity, 1e-6)
        guard = c * max(ref, backlog, est)

        if slack <= guard:
            return m + (guard - slack) / max(guard, 1e-6) + 0.01 * score
        else:
            return score - demote * (slack / max(guard, 1e-6))

    return score  # tuned (due_w=0.923,spt_w=0.0136,age_w=0.0299,c=3.68,demote=0.184,m=6.68e+05,floor=0.305)

import math
def priority(task, state, guard=1.1, k=0.7, m=4.0, hi=1e8,
             age=1.0, cap=50.0, tail=2.0, tail_hi=1e7,
             alpha=1.0, sizep=0.0, fit_boost=0.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    now = state.now
    wait = max(0.0, now - task.release)
    weight = max(task.weight, 1e-6)
    slack = task.due - est - now
    if task.tenant == 'premium':
        threshold = guard * max(mean, est)
        if slack <= 0.0:
            return hi + (-slack) / max(est + mean, 1e-6) + weight / est + wait / max(est + mean, 1e-6)
        elif slack <= threshold:
            return 0.5 * hi + (threshold - slack) / max(mean, 1e-6) + weight / est + wait / max(est + mean, 1e-6)
        else:
            return m * weight / est * math.exp(-(slack - threshold) / max(k * mean, 1e-6)) + wait / max(est + mean, 1e-6)
    else:
        ratio = wait / max(est + mean, 1e-6)
        short = weight / max(est ** alpha, 1e-6)
        if ratio >= tail:
            return tail_hi + ratio + short
        capv = max(state.capacity, 1e-6)
        size_pen = 1.0 / max(1.0 + sizep * task.resource_need / capv, 1e-6)
        miss = max(0.0, task.resource_need - state.free) / capv
        fit = 1.0 / max(1.0 + fit_boost * miss, 1e-6)
        return short * (1.0 + age * min(cap, ratio)) * size_pen * fit  # tuned (guard=0.853,k=0.27,m=2.36,hi=1.02e+08,age=3.09,cap=26.4,tail=5.15,tail_hi=1.94e+07,alpha=0.269,sizep=0,fit_boost=0)

import math
def priority(task, state, m=8.0, k=1.0, c=1.0, alpha=0.5, beta=0.5, fit_bonus=0.5, pack_bonus=0.5, guard=1e6, urgent=0.5, age_bonus=0.3, age_scale=1.5, age_cap=50.0, map_f=1.0, red_f=1.0, join_f=1.0, other_f=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean_est = max(state.mean_est, 1e-6)
    if task.tenant == 'premium':
        slack = task.due - state.now - est
        denom = max(k * mean_est, 1e-6)
        score = m * max(task.weight, 1e-6) / est - slack / denom
        if slack < 0.0:
            return guard + score - slack / mean_est
        if slack <= urgent * mean_est:
            score += guard * (1.0 - slack / max(urgent * mean_est, 1e-6))
        return score
    else:
        if task.task_type == 'map':
            tf = map_f
        elif task.task_type == 'reduce':
            tf = red_f
        elif task.task_type == 'join':
            tf = join_f
        else:
            tf = other_f
        eff = max(est * max(tf, 1e-6), 1e-6)
        area = max((eff ** alpha) * (cores ** beta), 1e-6)
        wait_ratio = wait / max(age_scale * mean_est, 1e-6)
        age = age_bonus * math.exp(min(age_cap, wait_ratio))
        hrr = (wait + c * eff) / area
        fit = 1.0 if cores <= state.free + 1e-9 else 0.0
        pack = cores / max(state.free, 1e-6)
        return hrr + age + fit_bonus * fit / max(cores, 1e-6) + pack_bonus * fit * pack  # tuned (m=28.3,k=1.45,c=2.81,alpha=0.265,beta=0.272,fit_bonus=0.443,pack_bonus=0.19,guard=2.65e+06,urgent=1.19,age_bonus=0.926,age_scale=0.608,age_cap=77,map_f=0.27,red_f=0.332,join_f=1.1,other_f=1.8)

import math
def priority(task, state, prem_m=6.0, guard=1.25, load_gain=0.75, age=1.0, cap=8.0, alpha=1.0, starve=100.0, target=3.0, emergency=1000000.0, fit_bonus=0.0):
    p = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    cap_cores = max(state.capacity, 1e-6)
    load = state.queue_work / cap_cores
    scale = max(p, mean, 1.0)
    fits = 1.0 if task.resource_need <= state.free + 1e-6 else 0.0
    if task.tenant == 'premium':
        slack = task.due - state.now - p
        delay = load_gain * load * scale
        if slack <= 0.0:
            return emergency + (1.0 + age * min(wait / p, cap) + wait / p) / p
        base = (1.0 + age * min(wait / p, cap) + fit_bonus * fits) / max(p ** alpha, 1e-6)
        effective_slack = slack + delay
        if effective_slack <= guard * scale:
            return prem_m * base + scale / max(effective_slack + scale, 1e-6)
        return base + 1.0 / max(effective_slack + 1.0, 1e-6)
    pressure = 1.0 + max(0.0, load - 0.5) * load_gain
    base = (1.0 + age * min(wait / p, cap) * pressure + fit_bonus * fits) / max(p ** alpha, 1e-6)
    budget = target * max(mean, p, 1.0) * (1.0 + load)
    if wait > budget:
        base += starve * (1.0 + (wait - budget) / max(mean, 1.0))
    return base  # tuned (prem_m=7.7,guard=0.796,load_gain=1.02,age=2.04,cap=3.5,alpha=0.339,starve=66.4,target=2.79,emergency=2.59e+05,fit_bonus=0)

def priority(task, state, m=10.0, b=0.0, a=4.0, cap=1e6, guard=1e6, risk=0.0, c=0.0, edf=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    if task.tenant == 'premium':
        slack = task.due - state.now - est
        qdelay = state.queue_work / max(state.capacity, 1e-6)
        if slack < risk * (est + qdelay) + c * state.mean_est:
            return guard + m / max(est, 1e-6) + edf * (state.now + est - task.due) / max(est, 1e-6)
        return m / max(est, 1e-6)
    age = wait / max(est, 1e-6)
    boost = b * max(0.0, age - a)
    if boost > cap:
        boost = cap
    return (1.0 + boost) / max(est, 1e-6)

import math
def priority(task, state, m=8.0, k=0.7, d=1.0, c=1.35, b=0.7, s=1.2, alpha=0.5, rho=1.0, eta=0.3, premium_tier=1e12, tail_tier=1e9):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    now = state.now
    wait = max(0.0, now - task.release)
    horizon = max(mean, state.queue_work / max(state.capacity, 1e-6), est)
    slack = task.due - now - est
    if task.tenant == 'premium':
        if slack < d * max(est, mean):
            return premium_tier - slack
        return m * task.weight / est * math.exp(-max(0.0, slack) / max(k * mean, 1e-6))
    if wait > c * horizon:
        return tail_tier + wait
    pressure = max(
        state.queue_work / max(state.capacity * mean, 1e-6),
        state.queue_len / max(state.capacity, 1.0)
    )
    age = 1.0 + b * wait / max(horizon, 1e-6)
    if pressure > rho:
        return task.weight * age / (max(task.resource_need, 1e-6) ** alpha)
    return task.weight * (age ** eta) / (max(est ** s, 1e-6) * max(task.resource_need, 1e-6) ** alpha)
